import unittest

from tallybook import errors
from tallybook.accounts import ChartError
from tallybook.currency import CurrencyError
from tallybook.dates import DateError
from tallybook.errors import (
    ConflictError,
    NotFoundError,
    ParseError,
    TallybookError,
    ValidationError,
)
from tallybook.ledger import LedgerError
from tallybook.money import MoneyError


class ErrorHierarchyTest(unittest.TestCase):
    def test_codes(self):
        rows = [
            (ParseError, "parse"),
            (ValidationError, "validation"),
            (NotFoundError, "not_found"),
            (ConflictError, "conflict"),
        ]
        for cls, code in rows:
            with self.subTest(cls=cls.__name__):
                self.assertEqual(cls("x").code, code)
                self.assertEqual(cls.code, code)

    def test_all_derive_from_tallybook_error(self):
        for cls in (ParseError, ValidationError, NotFoundError, ConflictError):
            with self.subTest(cls=cls.__name__):
                self.assertTrue(issubclass(cls, TallybookError))
        self.assertTrue(issubclass(TallybookError, Exception))

    def test_four_kinds_are_distinct(self):
        classes = (ParseError, ValidationError, NotFoundError, ConflictError)
        for a in classes:
            for b in classes:
                if a is not b:
                    with self.subTest(a=a.__name__, b=b.__name__):
                        self.assertFalse(issubclass(a, b))

    def test_message_attribute(self):
        for cls in (ParseError, ValidationError, NotFoundError, ConflictError):
            with self.subTest(cls=cls.__name__):
                self.assertEqual(cls("something broke").message, "something broke")

    def test_str_is_message(self):
        for cls in (TallybookError, ParseError, ValidationError, NotFoundError, ConflictError):
            with self.subTest(cls=cls.__name__):
                self.assertEqual(str(cls("it's \"odd\"\n")), "it's \"odd\"\n")

    def test_raise_and_catch_as_base(self):
        with self.assertRaises(TallybookError) as cm:
            raise NotFoundError("gone")
        self.assertEqual(cm.exception.code, "not_found")
        self.assertEqual(cm.exception.message, "gone")

    def test_detail_defaults_to_empty_dict(self):
        self.assertEqual(ValidationError("m").detail, {})

    def test_detail_is_copied(self):
        src = {"line": 3}
        err = ParseError("m", src)
        src["line"] = 4
        self.assertEqual(err.detail, {"line": 3})

    def test_module_errors_derive_from_named_base(self):
        rows = [
            (MoneyError, ValidationError, "validation"),
            (CurrencyError, ValidationError, "validation"),
            (DateError, ParseError, "parse"),
            (ChartError, ValidationError, "validation"),
            (LedgerError, ValidationError, "validation"),
        ]
        for cls, base, code in rows:
            with self.subTest(cls=cls.__name__):
                self.assertTrue(issubclass(cls, base))
                self.assertEqual(cls("m").code, code)

    def test_module_exports(self):
        for name in ("TallybookError", "ParseError", "ValidationError", "NotFoundError", "ConflictError"):
            with self.subTest(name=name):
                self.assertTrue(hasattr(errors, name))


if __name__ == "__main__":
    unittest.main()

